$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root
Write-Host 'N-MEGA4 builder closure uygulanıyor...' -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'scripts') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $Root 'src\certification\player-readiness') | Out-Null
[IO.File]::WriteAllBytes((Join-Path $Root 'scripts\n-mega4-builder-choice-validation-audit.mjs'),[Convert]::FromBase64String(''))
[IO.File]::WriteAllBytes((Join-Path $Root 'src\certification\player-readiness\nMega4Audit.test.ts'),[Convert]::FromBase64String(''))
$Patch=@'
import fs from "node:fs";const f="package.json",p=JSON.parse(fs.readFileSync(f,"utf8"));p.scripts??={};p.scripts["audit:player-system:n-mega4"]="node scripts/n-mega4-builder-choice-validation-audit.mjs";p.scripts["test:n-mega4"]="vitest run src/certification/player-readiness/nMega4Audit.test.ts src/core/rulesets/characterValidation.test.ts src/core/rulesets/proficiencyRules.test.ts src/core/rulesets/levelOneProficiencyReadiness.test.ts src/core/rulesets/unifiedCharacterChoices.test.ts src/core/rulesets/levelUpChoiceCompletion.test.ts src/core/rulesets/choiceDebt.test.ts src/core/rulesets/featRules.test.ts src/core/rulesets/featOfficialCertification.test.ts src/core/rulesets/fightingStyleRules.test.ts src/core/rulesets/fightingStyleRuntimeRules.test.ts src/core/rulesets/invocationRules.test.ts src/core/rulesets/metamagicRules.test.ts src/core/rulesets/maneuverRules.test.ts src/core/rulesets/weaponMasteryRuntimeRules.test.ts src/core/rulesets/ancestryChoiceRules.test.ts src/core/rulesets/equipmentRules.test.ts src/core/rulesets/levelOneEquipmentReadiness.test.ts src/core/rulesets/classSpellSelectionRules.test.ts src/core/rulesets/levelOneSpellcastingReadiness.test.ts src/core/rulesets/builderProgress.test.ts src/core/rulesets/singleClassBuilderUiRules.test.ts src/core/rulesets/singleClassBuilderFinalCertification.integration.test.ts src/core/rulesets/builderSpellIntegration.test.ts src/core/rulesets/highLevelAbilityBuilder.test.ts";p.scripts["certify:n-mega4"]="npm run audit:player-system:n-mega4 && npm run test:n-mega4 && npm run build";fs.writeFileSync(f,JSON.stringify(p,null,2)+"\n");
'@
$tmp=Join-Path $env:TEMP 'e4-nmega4-patch.mjs';Set-Content $tmp $Patch -Encoding UTF8;node $tmp;Remove-Item $tmp -Force
if(Test-Path (Join-Path $Root 'patch')){Remove-Item (Join-Path $Root 'patch') -Recurse -Force}
if(Test-Path (Join-Path $Root 'payload')){Remove-Item (Join-Path $Root 'payload') -Recurse -Force}
Write-Host 'N-MEGA4 audit + geniş builder regression + build çalıştırılıyor...' -ForegroundColor Yellow
npm.cmd run certify:n-mega4
if($LASTEXITCODE-ne 0){throw 'N-MEGA4 sertifikasyonu başarısız oldu. Terminal çıktısını gönderin.'}
Write-Host 'N-MEGA4 GREEN' -ForegroundColor Green
Write-Host 'Rapor: certification-reports\n-mega4\N_MEGA4_SUMMARY.md'
